input.new_string:
if balance_cents < 0 or days_late < 0:
    raise ValueError("balance_cents and days_late must be non-negative")
if balance_cents == 0 or days_late <= GRACE_DAYS:
    return 0
# Calculate periods: days 1-30 = period 1, days 31-60 = period 2, etc.
periods = (days_late + PERIOD_DAYS - 1) // PERIOD_DAYS
# Calculate fee with half-up rounding (add 5000 before dividing by 10000)
fee = (balance_cents * RATE_BP * periods + 5000) // 10000
# Apply cap and minimum: cap wins if fee exceeds it, otherwise apply minimum
cap = balance_cents // 5
if fee > cap:
    return cap
return max(fee, MINIMUM_FEE_CENTS)
